<html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>UTTC Website CMS & AI Operations</title>
<style>
:root{--navy:#142d4e;--green:#237a57;--bg:#f3f5f8;--ink:#17283d;--muted:#64748b;--line:#e5eaf0;--red:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"Noto Sans Bengali",system-ui,sans-serif}button,input,textarea,select{font:inherit}.top{background:var(--navy);color:white;padding:16px max(18px,calc((100% - 1180px)/2));display:flex;justify-content:space-between;align-items:center;gap:12px}.top a{color:white}.wrap{max-width:1180px;margin:auto;padding:24px 16px}.intro{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.muted{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.stat,.panel,.item{background:white;border:1px solid var(--line);border-radius:14px;padding:16px}.stat b{font-size:24px;display:block}.columns{display:grid;grid-template-columns:minmax(300px,.85fr) minmax(0,1.15fr);gap:16px}.field{display:grid;gap:6px;margin:12px 0}.field label{font-weight:650;font-size:13px}.field input,.field textarea,.field select{border:1px solid #d4dce6;border-radius:9px;padding:10px;width:100%;background:white}.field textarea{min-height:120px}.btn{border:0;border-radius:9px;background:var(--green);color:white;padding:10px 14px;cursor:pointer;font-weight:650}.btn.alt{background:#eaf0f5;color:var(--navy)}.btn.red{background:#fff0ef;color:var(--red)}.actions{display:flex;gap:7px;flex-wrap:wrap}.list{display:grid;gap:10px}.itemhead{display:flex;justify-content:space-between;gap:8px}.pill{font-size:11px;border-radius:30px;background:#fff4d6;padding:4px 8px}.pill.live{background:#e7f5ed;color:#176344}.notice{padding:12px;border-radius:9px;margin:12px 0;display:none}.notice.show{display:block;background:#e7f5ed}.notice.err{background:#fff0ef;color:var(--red)}.ops{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.ops div{background:#f8fafc;border:1px solid var(--line);border-radius:10px;padding:12px}.ops small{display:block;color:var(--muted)}@media(max-width:800px){.columns{grid-template-columns:1fr}.grid,.ops{grid-template-columns:repeat(2,1fr)}}@media(max-width:420px){.grid,.ops{grid-template-columns:1fr 1fr}.wrap{padding:16px 12px}}
</style></head><body>
<header class="top"><strong>UTTC · Website CMS & AI Operations</strong><nav><a href="index.php">Knowledge Base</a>　<a href="../">Public Website</a></nav></header>
<main class="wrap"><div class="intro"><div><h1>Website Admin Panel</h1><p class="muted">কোর্স, নোটিশ, গ্যালারি, পেজ ও যোগাযোগের তথ্য পরিচালনা করুন। পরিবর্তন প্রথমে Draft থাকবে।</p></div><button class="btn alt" id="refresh">রিফ্রেশ</button></div>
<div id="notice" class="notice"></div>
<section class="panel"><h2>AI Operations Status</h2><p class="muted">কোনো API key বা secret এখানে প্রদর্শিত হয় না।</p><div class="ops" id="ops"><div>লোড হচ্ছে…</div></div></section>
<div class="grid"><div class="stat"><span class="muted">মোট CMS রেকর্ড</span><b id="total">০</b></div><div class="stat"><span class="muted">Draft</span><b id="draft">০</b></div><div class="stat"><span class="muted">Published</span><b id="published">০</b></div><div class="stat"><span class="muted">AI Published Knowledge</span><b id="kb">০</b></div></div>
<div class="columns"><section class="panel"><h2 id="heading">নতুন তথ্য যোগ করুন</h2><form id="form"><input id="id" type="hidden">
<div class="field"><label for="type">তথ্যের ধরন</label><select id="type"><option value="course">কোর্স</option><option value="notice">নোটিশ</option><option value="gallery">গ্যালারি</option><option value="page">পেজের তথ্য</option><option value="contact">যোগাযোগ</option><option value="menu">Navigation Menu</option></select></div>
<div class="field"><label for="title">শিরোনাম</label><input id="title" maxlength="180" required></div>
<div class="field"><label for="body">বিস্তারিত বিবরণ</label><textarea id="body" maxlength="12000" required></textarea></div>
<div class="field"><label for="url">সম্পর্কিত HTTPS লিংক (ঐচ্ছিক)</label><input id="url" type="url" placeholder="https://..."></div>
<div class="field"><label for="image">ছবির HTTPS URL (ঐচ্ছিক)</label><input id="image" type="url" placeholder="https://..."></div>
<div class="field"><label for="slug">Slug / পেজ আইডি (ঐচ্ছিক)</label><input id="slug" maxlength="180"></div><div class="field"><label for="metaTitle">SEO Title (ঐচ্ছিক)</label><input id="metaTitle" maxlength="180"></div><div class="field"><label for="metaDescription">SEO Meta Description (ঐচ্ছিক)</label><textarea id="metaDescription" maxlength="320" style="min-height:76px"></textarea></div><div class="field"><label for="canonical">Canonical HTTPS URL (ঐচ্ছিক)</label><input id="canonical" type="url" placeholder="https://uttc.edu.bd/..."></div>
<div class="actions"><button class="btn" type="submit">Draft সংরক্ষণ</button><button class="btn alt" type="button" id="reset">পরিষ্কার</button></div></form></section>
<section class="panel"><div class="intro"><h2>সংরক্ষিত কনটেন্ট</h2><select id="filter"><option value="">সব ধরন</option><option value="course">কোর্স</option><option value="notice">নোটিশ</option><option value="gallery">গ্যালারি</option><option value="page">পেজ</option><option value="contact">যোগাযোগ</option><option value="menu">মেনু</option></select></div><div id="list" class="list"><p class="muted">তথ্য লোড হচ্ছে…</p></div></section></div><dialog id="previewDialog" aria-labelledby="previewTitle" style="width:min(680px,calc(100% - 24px));border:1px solid var(--line);border-radius:14px;padding:22px;color:var(--ink);box-shadow:0 20px 60px #142d4e33"><div class="intro"><h2 id="previewTitle">কনটেন্ট প্রিভিউ</h2><button class="btn alt" type="button" id="closePreview">বন্ধ করুন</button></div><p class="muted" id="previewType"></p><h3 id="previewHeading"></h3><p id="previewBody" style="white-space:pre-wrap;overflow-wrap:anywhere"></p><img id="previewImage" alt="" hidden style="max-width:100%;height:auto;border-radius:10px"><p><a id="previewLink" target="_blank" rel="noopener noreferrer" hidden>সম্পর্কিত লিংক খুলুন</a></p><p class="muted">এটি CMS-এর Draft/Published তথ্যের প্রিভিউ; পাবলিক পেজের চূড়ান্ত বিন্যাসের নিশ্চয়তা নয়।</p></dialog>
<p class="muted">সতর্কতা: এই CMS-এর Published রেকর্ড read-only API-তে পাওয়া যায়। বিদ্যমান HTML পেজে স্বয়ংক্রিয়ভাবে প্রতিটি কনটেন্ট বসানো এখনো আলাদা integration ধাপ; প্রকাশের আগে Preview ও public page QA প্রয়োজন। AI Knowledge Base-এর Draft/Publish আলাদা থাকে।</p></main>
<script>
const API='../api/cms.php';let csrf='',items=[],ops={};const $=id=>document.getElementById(id);const bn=n=>new Intl.NumberFormat('bn-BD').format(n);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function note(s,err=false){$('notice').textContent=s;$('notice').className='notice show'+(err?' err':'');}
async function req(action,data={}){const r=await fetch(API+(action==='token'?'?action=token':''),action==='token'?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf,...data})});const d=await r.json().catch(()=>({ok:false,message:'সার্ভারের উত্তর পাওয়া যায়নি।'}));if(r.status===401){location.href='index.php';throw new Error('লগইন প্রয়োজন।');}if(!r.ok||!d.ok)throw new Error(d.message||'অনুরোধ ব্যর্থ।');return d;}
function reset(){ $('form').reset();$('id').value='';$('heading').textContent='নতুন তথ্য যোগ করুন';}
function render(){const q=$('filter').value;const arr=items.filter(x=>!q||x.type===q);$('total').textContent=bn(items.length);$('draft').textContent=bn(items.filter(x=>x.status!=='published').length);$('published').textContent=bn(items.filter(x=>x.status==='published').length);$('kb').textContent=bn(ops.knowledge_published||0);$('list').innerHTML=arr.length?arr.map(x=>'<article class="item"><div class="itemhead"><strong>'+esc(x.title)+'</strong><span class="pill '+(x.status==='published'?'live':'')+'">'+(x.status==='published'?'Published':'Draft')+'</span></div><p class="muted">'+esc(({course:'কোর্স',notice:'নোটিশ',gallery:'গ্যালারি',page:'পেজ',contact:'যোগাযোগ',menu:'মেনু'})[x.type]||x.type)+' · '+esc(x.updated_at||'')+'</p><p>'+esc(x.body.slice(0,220))+'</p><div class="actions"><button class="btn alt" data-preview="'+esc(x.id)+'">Preview</button><button class="btn alt" data-edit="'+esc(x.id)+'">সম্পাদনা</button>'+(x.status==='published'?'':'<button class="btn" data-pub="'+esc(x.id)+'">Publish</button>')+'<button class="btn red" data-del="'+esc(x.id)+'">মুছুন</button></div></article>').join(''):'<p class="muted">এখনো কোনো রেকর্ড নেই।</p>';
$('ops').innerHTML=[['OpenAI API',ops.openai_configured?'Configured':'Not configured'],['Embedding',ops.embedding_configured?'Configured':'BM25 fallback'],['Admin password',ops.admin_password_configured?'Configured':'Missing'],['Indexed pages',bn(ops.website_indexed||0)],['AI published entries',bn(ops.knowledge_published||0)],['PHP version',ops.php_version||'—'],['Last CMS update',ops.last_cms_update||'এখনো নয়']].map(x=>'<div><small>'+esc(x[0])+'</small><strong>'+esc(x[1])+'</strong></div>').join('');}
async function load(){const d=await req('list');items=d.items||[];ops=d.operations||{};render();}
$('form').addEventListener('submit',async e=>{e.preventDefault();try{await req('save',{id:$('id').value,type:$('type').value,title:$('title').value,body:$('body').value,url:$('url').value,image_url:$('image').value,slug:$('slug').value,meta_title:$('metaTitle').value,meta_description:$('metaDescription').value,canonical_url:$('canonical').value});note('Draft সংরক্ষণ হয়েছে। যাচাই শেষে Publish করুন।');reset();await load();}catch(e){note(e.message,true);}});
function preview(item){$('previewType').textContent=({course:'কোর্স',notice:'নোটিশ',gallery:'গ্যালারি',page:'পেজ',contact:'যোগাযোগ',menu:'মেনু'})[item.type]||item.type;$('previewHeading').textContent=item.title||'';$('previewBody').textContent=item.body||'';const image=item.image_url||'';let validImage=false;try{const u=new URL(image);validImage=u.protocol==='https:'&&!u.username&&!u.password;}catch(_){}$('previewImage').hidden=!validImage;if(validImage){$('previewImage').src=image;$('previewImage').alt=item.title||'';}const link=item.url||'';let validLink=false;try{const u=new URL(link);validLink=u.protocol==='https:'&&!u.username&&!u.password;}catch(_){}$('previewLink').hidden=!validLink;if(validLink)$('previewLink').href=link;$('previewDialog').showModal();}
$('closePreview').onclick=()=>$('previewDialog').close();$('previewDialog').addEventListener('click',e=>{if(e.target===$('previewDialog'))$('previewDialog').close();});
$('list').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const item=items.find(x=>x.id===(b.dataset.preview||b.dataset.edit||b.dataset.pub||b.dataset.del));try{if(b.dataset.preview){preview(item);}else if(b.dataset.edit){$('id').value=item.id;$('type').value=item.type;$('title').value=item.title;$('body').value=item.body;$('url').value=item.url||'';$('image').value=item.image_url||'';$('slug').value=item.slug||'';$('metaTitle').value=item.meta_title||'';$('metaDescription').value=item.meta_description||'';$('canonical').value=item.canonical_url||'';$('heading').textContent='তথ্য সম্পাদনা করুন';window.scrollTo({top:0,behavior:'smooth'});}else if(b.dataset.pub){if(!confirm('তথ্য যাচাই করা হয়েছে এবং প্রকাশ করবেন?'))return;await req('publish',{id:item.id});note('তথ্য প্রকাশিত হয়েছে।');await load();}else if(b.dataset.del){if(!confirm('রেকর্ডটি মুছে ফেলবেন?'))return;await req('delete',{id:item.id});note('রেকর্ড মুছে ফেলা হয়েছে।');await load();}}catch(e){note(e.message,true);}});
$('refresh').onclick=()=>load().catch(e=>note(e.message,true));$('filter').onchange=render;$('reset').onclick=reset;
(async()=>{try{const t=await req('token');csrf=t.csrf;await load();}catch(e){note(e.message,true);}})();
</script></body></html>